  const makeTemporaryPassword=()=>{const characters='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';return Array.from(crypto.getRandomValues(new Uint32Array(18)),value=>characters[value%characters.length]).join('')}
